from pathlib import Path
import pandas as pd,numpy as np,json,hashlib
R=Path(__file__).resolve().parent;ROOT=R.parent;C=R/'holder_capture';A=ROOT/'archive972/shareholder_system_972';oldcodes=set(pd.read_csv(A/'qualified_972.csv',dtype={'code':str}).code);pool=set(pd.read_csv(ROOT/'qualified_1494.csv',dtype={'code':str}).code);newcodes=pool-oldcodes
