 frame['SOURCE_TABLE']=label;frame['SOURCE_NOTICE_FIELD']=noticefield;frame['SOURCE_HOLDER_FIELD']=holderfield;frame['SOURCE_NOTICE_VERIFICATION']='frozen_provider_date_not_full_primary_notice_verification' if label.startswith('FROZEN') else 'provider_date_not_full_primary_notice_verification'
