qa={'status':'complete','pool':1494,'captured':manifest['counts'],'main_rows':len(main),'main_stocks':main.SECURITY_CODE.nunique(),'baseline2009_rows':len(base),'baseline2009_stocks':base.SECURITY_CODE.nunique(),'expected_old_main_rows':241976,'expected_old_baseline_rows':1465,'main_count_equals_old':len(main)==241976,'baseline_count_equals_old':len(base)==1465,'all_overlap_rows':len(j),'overlap_A_mismatches':int((~j.A_matches).sum()),'overlap_notice_mismatches':int((~j.notice_matches).sum()),'dual_class_rows':len(dual),'dual_class_A_match':int(dual.A_matches.sum()),'F10_missing_nonpositiveA':int((~validA).sum()),'F10_invalid_dates':int((~validdate).sum()),'F10_added_after_precedence':len(mapped),'frozen972_2019plus_rows':len(expected),'frozen972_2019plus_key_values_exact':True,'negative_lag_raw_main':int((main.END_DATE>main.HOLD_NOTICE_DATE).sum()),'year_counts':main.HOLD_NOTICE_DATE.str[:4].value_counts().sort_index().to_dict(),'raw_pages_SHA_verified':True,'old_full1494_membership_archive_unavailable':True,'source_priority':['Frozen qualified972 original2019+ rows preserved; archive extra candidate codes are not part of freeze','DET preferred for endpoint keys; F10 fills missing endpoint keys only','F10 HOLDER_A_NUM only; unknown share capital left NaN; negative lag or missing A quarantined','Archive-extra 001232 and301686 are added522 source; their35 archived rows match recaptured date/count exactly'],'archive_candidate_extra_comparison':'ARCHIVE_EXTRA_CODES_COMPARISON.csv','limits':['Recovered1494 from frozen972+new public snapshots; matching count is not proof of identical old1494 membership','All old8-cell curve statistics must be compared with saved frozen15UI before addingpositive80tail','F10 uses A counts only; no TOTAL fallback; DET endpoint precedence; frozen9722019plus never replaced']}
